package org.example.board.post;

import java.net.URI;

import jakarta.validation.Valid;
import org.example.board.auth.LoginUser;
import org.example.board.common.ApiResponse;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class PostController {

    private final PostService postService;

    public PostController(PostService postService) {
        this.postService = postService;
    }

    @PostMapping("/api/v1/posts")
    public ResponseEntity<ApiResponse<PostResponse>> create(@LoginUser Long userId,
                                                            @Valid @RequestBody PostCreateRequest request) {
        PostResponse created = postService.create(userId, request);
        return ResponseEntity.created(URI.create("/api/v1/posts/" + created.id()))
                .body(ApiResponse.created(created));
    }
}

